I ran into a temporary issue with the live preview sandbox, but I have the complete interactive module ready for you! 

Below is a full **Solar System Explorer** — a self-contained HTML file in the spirit of Microsoft Encarta's interactive tours. It features a real-time 3D orrery, clickable planets with fact cards, a sidebar navigator, and an auto-pilot "Tour" mode.

### What you can do with it
- **Click any planet** in 3D space to zoom in and reveal an info panel with facts and classification tags.
- **Use the left sidebar** to jump directly to any planet.
- **Press "Start Tour"** to auto-navigate through the solar system like an Encarta guided presentation.
- **Drag / scroll / right-click** to freely explore in full 3D.

### How to run
1. Copy the code below into a file named **`solar_system.html`**.
2. Open it in any modern web browser (Chrome, Edge, Firefox, Safari).
3. No build step or installation needed — it loads Three.js from a CDN automatically.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Solar System Explorer</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700&display=swap');
  * { box-sizing: border-box; }
  body { margin: 0; overflow: hidden; background: #02040a; font-family: 'Inter', sans-serif; color: #e0ecff; }
  #canvas-container { position: absolute; inset: 0; z-index: 0; }
  #ui-layer { position: absolute; inset: 0; z-index: 10; pointer-events: none; display: flex; flex-direction: column; }
  .top-bar { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; pointer-events: auto; }
  .brand h1 { margin: 0; font-size: 1.25rem; font-weight: 700; color: #fff; text-shadow: 0 2px 8px rgba(0,0,0,0.5); }
  .brand span { font-size: 0.85rem; opacity: 0.7; font-weight: 300; }
  .top-actions { display: flex; gap: 10px; }
  button.action-btn { background: rgba(16, 40, 80, 0.7); border: 1px solid rgba(120, 180, 255, 0.25); color: #cce4ff; padding: 8px 16px; border-radius: 6px; cursor: pointer; font-weight: 500; backdrop-filter: blur(8px); transition: all 0.2s; pointer-events: auto; }
  button.action-btn:hover { background: rgba(30, 80, 160, 0.8); border-color: rgba(120, 180, 255, 0.6); color: #fff; }
  button.action-btn.active { background: rgba(255, 170, 0, 0.2); border-color: rgba(255, 170, 0, 0.6); color: #ffcc66; }
  .sidebar { position: absolute; left: 20px; top: 80px; width: 220px; background: rgba(6, 16, 36, 0.75); border: 1px solid rgba(120, 180, 255, 0.12); border-radius: 10px; padding: 12px; pointer-events: auto; backdrop-filter: blur(10px); }
  .sidebar h3 { margin: 0 0 10px 0; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px; opacity: 0.6; border-bottom: 1px solid rgba(120,180,255,0.15); padding-bottom: 8px; }
  .nav-item { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 6px; cursor: pointer; transition: background 0.2s; font-size: 0.95rem; }
  .nav-item:hover { background: rgba(255,255,255,0.07); }
  .nav-item.active { background: rgba(33, 150, 243, 0.2); color: #82c4ff; }
  .dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; box-shadow: 0 0 6px currentColor; }
  .info-panel { position: absolute; right: 20px; top: 80px; width: 340px; background: rgba(6, 16, 36, 0.85); border: 1px solid rgba(120, 180, 255, 0.15); border-radius: 10px; padding: 22px; pointer-events: auto; backdrop-filter: blur(12px); transform: translateX(120%); transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1); max-height: calc(100vh - 120px); overflow-y: auto; }
  .info-panel.active { transform: translateX(0); }
  .info-panel h2 { margin: 0 0 10px 0; font-size: 1.6rem; color: #82c4ff; }
  .info-panel .tagline { margin: 0 0 14px 0; font-size: 1rem; opacity: 0.9; line-height: 1.4; font-weight: 300; }
  .info-panel ul { margin: 0; padding-left: 18px; }
  .info-panel li { margin-bottom: 8px; line-height: 1.4; font-size: 0.95rem; opacity: 0.9; }
  .info-panel .meta { display: flex; gap: 12px; margin-top: 16px; flex-wrap: wrap; }
  .meta-chip { background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.1); padding: 4px 10px; border-radius: 20px; font-size: 0.8rem; }
  .hud-bottom { position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%); background: rgba(6, 16, 36, 0.7); border: 1px solid rgba(120, 180, 255, 0.1); border-radius: 8px; padding: 10px 20px; font-size: 0.85rem; opacity: 0.8; pointer-events: auto; backdrop-filter: blur(6px); white-space: nowrap; }
</style>
</head>
<body>
<div id="canvas-container"></div>
<div id="ui-layer">
  <div class="top-bar">
    <div class="brand">
      <div>
        <h1>☀️ Solar System Explorer</h1>
        <span>An interactive Encarta-style learning module</span>
      </div>
    </div>
    <div class="top-actions">
      <button id="btn-tour" class="action-btn" onclick="toggleTour()">▶ Start Tour</button>
      <button class="action-btn" onclick="resetView()">⟲ Reset View</button>
    </div>
  </div>
  <div class="sidebar">
    <h3>Jump to Planet</h3>
    <div id="planet-list"></div>
  </div>
  <div id="info-panel" class="info-panel">
    <h2 id="p-name">Planet</h2>
    <p id="p-desc" class="tagline">Description...</p>
    <ul id="p-facts"></ul>
    <div id="p-meta" class="meta"></div>
  </div>
  <div class="hud-bottom">
    🖱️ Click a planet to explore • Drag to orbit • Scroll to zoom • Right-click to pan
  </div>
</div>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
    "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
  }
}
</script>
<script type="module">
  import * as THREE from 'three';
  import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

  const container = document.getElementById('canvas-container');
  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x02040a, 0.0008);

  const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 3000);
  camera.position.set(80, 120, 220);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.toneMapping = THREE.ReinhardToneMapping;
  container.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.06;
  controls.minDistance = 25;
  controls.maxDistance = 900;
  controls.target.set(0, 0, 0);

  scene.add(new THREE.AmbientLight(0x404860, 0.6));
  const sunLight = new THREE.PointLight(0xffddaa, 3, 500, 1);
  sunLight.position.set(0, 0, 0);
  scene.add(sunLight);

  const starGeo = new THREE.BufferGeometry();
  const starCount = 6000;
  const starPos = new Float32Array(starCount * 3);
  for (let i = 0; i < starCount * 3; i++) starPos[i] = (Math.random() - 0.5) * 1200;
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.8, transparent: true, opacity: 0.7, sizeAttenuation: true });
  scene.add(new THREE.Points(starGeo, starMat));

  const sunMesh = new THREE.Mesh(new THREE.SphereGeometry(11, 48, 48), new THREE.MeshBasicMaterial({ color: 0xffdd44 }));
  scene.add(sunMesh);

  function makeGlow(r, c, o) {
    const g = new THREE.SphereGeometry(r, 32, 32);
    const m = new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: o, blending: THREE.AdditiveBlending, side: THREE.BackSide, depthWrite: false });
    return new THREE.Mesh(g, m);
  }
  scene.add(makeGlow(18, 0xffaa00, 0.25));
  scene.add(makeGlow(28, 0xff8800, 0.12));
  scene.add(makeGlow(42, 0xff4400, 0.05));

  const planetsData = [
    { name: "Mercury", dist: 32, size: 1.8, speed: 0.025, color: 0x9e9e9e, desc: "The smallest planet and closest to the Sun.", facts: ["Orbital period: 88 Earth days", "Has no atmosphere to trap heat", "Surface temps range from -180°C to 430°C", "Heavily cratered like our Moon"], type: "Terrestrial" },
    { name: "Venus", dist: 48, size: 3.0, speed: 0.018, color: 0xffa726, desc: "A toxic, blazing world shrouded in thick clouds.", facts: ["Hottest planet at ~465°C surface", "Thick CO₂ atmosphere with sulfuric acid clouds", "Rotates backwards very slowly", "A day on Venus is longer than its year"], type: "Terrestrial" },
    { name: "Earth", dist: 68, size: 3.2, speed: 0.012, color: 0x2196f3, desc: "Our home — the only known harbor for life.", facts: ["71% of surface covered by water", "Atmosphere is 78% nitrogen, 21% oxygen", "Has one large natural satellite: the Moon", "Active plate tectonics recycle the crust"], type: "Terrestrial" },
    { name: "Mars", dist: 90, size: 2.6, speed: 0.009, color: 0xe64a19, desc: "The Red Planet, cold, rocky, and full of dust.", facts: ["Home to Olympus Mons, tallest volcano", "Two small moons: Phobos & Deimos", "Roamed by NASA rovers seeking ancient life", "Iron oxide dust gives it a red color"], type: "Terrestrial" },
    { name: "Jupiter", dist: 130, size: 9.5, speed: 0.0045, color: 0xd4a373, desc: "The king of planets, a gas giant storm-watcher.", facts: ["Great Red Spot is a centuries-old storm", "Over 95 known moons", "Strong magnetic field & radiation belts", "Acts as a 'vacuum cleaner' for inner solar system"], type: "Gas Giant" },
    { name: "Saturn", dist: 175, size: 8.0, speed: 0.0032, color: 0xe0d5a8, desc: "The crown jewel, famous for its ring system.", facts: ["Rings made of ice, rock, and dust", "Less dense than water — it would float", "Largest moon Titan has rivers of methane", "Dozens of moons shepherd the ring shapes"], type: "Gas Giant" },
    { name: "Uranus", dist: 215, size: 5.8, speed: 0.0022, color: 0x4dd0e1, desc: "An icy blue world that rolls on its side.", facts: ["Axial tilt of 98° — it rotates on its side", "Coldest planetary atmosphere at -224°C", "Methane gas absorbs red light, reflecting blue", "Discovered in 1781 by William Herschel"], type: "Ice Giant" },
    { name: "Neptune", dist: 255, size: 5.5, speed: 0.0018, color: 0x3f51b5, desc: "Deep blue, distant, and whipped by supersonic winds.", facts: ["Fastest winds in the solar system: 2,100 km/h", "Discovered by math before telescope", "Moon Triton orbits backwards (retrograde)", "Takes 165 Earth years to orbit the Sun"], type: "Ice Giant" }
  ];

  const planetMeshes = [];
  const planetAngles = planetsData.map(() => Math.random() * Math.PI * 2);

  planetsData.forEach((p, i) => {
    const mat = new THREE.MeshStandardMaterial({ color: p.color, roughness: 0.9, metalness: 0.05 });
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(p.size, 40, 40), mat);
    mesh.userData = { ...p, index: i };
    scene.add(mesh);
    planetMeshes.push(mesh);

    const pts = [];
    for (let j = 0; j <= 100; j++) {
      const a = (j / 100) * Math.PI * 2;
      pts.push(new THREE.Vector3(Math.cos(a) * p.dist, 0, Math.sin(a) * p.dist));
    }
    const geo = new THREE.BufferGeometry().setFromPoints(pts);
    scene.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.12 })));

    if (p.name === "Saturn") {
      const ringGeo = new THREE.RingGeometry(p.size + 1.5, p.size + 7, 64);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0xddcc99, side: THREE.DoubleSide, transparent: true, opacity: 0.55 });
      const ring = new THREE.Mesh(ringGeo, ringMat);
      ring.rotation.x = Math.PI / 2;
      mesh.add(ring);
    }
  });

  const listEl = document.getElementById('planet-list');
  planetsData.forEach((p, i) => {
    const el = document.createElement('div');
    el.className = 'nav-item';
    el.dataset.index = i;
    el.innerHTML = `<div class="dot" style="background:#${new THREE.Color(p.color).getHexString()};color:#${new THREE.Color(p.color).getHexString()}"></div> ${p.name}`;
    el.addEventListener('click', () => selectPlanet(planetMeshes[i]));
    listEl.appendChild(el);
  });

  function updateNav(index) {
    document.querySelectorAll('.nav-item').forEach((el, i) => el.classList.toggle('active', i === index));
  }

  const raycaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();
  let selectedPlanet = null;
  let targetCamPos = null;
  let targetLookAt = new THREE.Vector3(0, 0, 0);
  let isTouring = false;
  let tourTimer = null;

  window.addEventListener('pointerdown', (e) => {
    if (e.target.closest('.sidebar, .top-bar, .info-panel')) return;
    mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);
    const hits = raycaster.intersectObjects(planetMeshes);
    if (hits.length > 0) {
      selectPlanet(hits[0].object);
      if (isTouring) stopTour();
    }
  });

  window.selectPlanet = selectPlanet;
  function selectPlanet(mesh) {
    selectedPlanet = mesh;
    const p = mesh.userData;
    updateNav(p.index);
    document.getElementById('p-name').innerText = p.name;
    document.getElementById('p-desc').innerText = p.desc;
    document.getElementById('p-facts').innerHTML = p.facts.map(f => `<li>${f}</li>`).join('');
    document.getElementById('p-meta').innerHTML = `<div class="meta-chip">${p.type}</div><div class="meta-chip">${p.dist}M km</div><div class="meta-chip">Scale ${p.size}x</div>`;
    document.getElementById('info-panel').classList.add('active');
    const offset = new THREE.Vector3(0, p.size * 2.5, p.size * 6.5);
    targetCamPos = mesh.position.clone().add(offset);
    targetLookAt.copy(mesh.position);
  }

  window.resetView = function () {
    selectedPlanet = null;
    document.getElementById('info-panel').classList.remove('active');
    targetCamPos = new THREE.Vector3(80, 120, 220);
    targetLookAt.set(0, 0, 0);
    updateNav(-1);
    if (isTouring) stopTour();
  };

  window.toggleTour = function () {
    if (isTouring) { stopTour(); return; }
    isTouring = true;
    document.getElementById('btn-tour').classList.add('active');
    document.getElementById('btn-tour').innerText = '⏸ Pause Tour';
    let idx = 0;
    function step() {
      if (!isTouring) return;
      selectPlanet(planetMeshes[idx]);
      idx = (idx + 1) % planetMeshes.length;
      tourTimer = setTimeout(step, 5000);
    }
    step();
  };

  function stopTour() {
    isTouring = false;
    clearTimeout(tourTimer);
    document.getElementById('btn-tour').classList.remove('active');
    document.getElementById('btn-tour').innerText = '▶ Start Tour';
  }

  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();
    planetMeshes.forEach((mesh, i) => {
      const p = planetsData[i];
      planetAngles[i] += p.speed * 0.4;
      mesh.position.x = Math.cos(planetAngles[i]) * p.dist;
      mesh.position.z = Math.sin(planetAngles[i]) * p.dist;
    });
    if (targetCamPos) {
      camera.position.lerp(targetCamPos, 0.035);
      controls.target.lerp(targetLookAt, 0.035);
    }
    sunMesh.rotation.y += 0.001;
    controls.update();
    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });
</script>
</body>
</html>
```

